#!/usr/bin/env python3
"""A shared todo list for a class, backed by one JSON file on a mount."""
import json
import os
import re
import uuid
from datetime import datetime, timezone
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

DATA_DIR = os.environ.get("DATA_DIR", "/data")
TODOS_FILE = os.path.join(DATA_DIR, "todos.json")
PORT = int(os.environ.get("PORT", "8080"))

TODO_ID_RE = re.compile(r"^/api/todos/([a-f0-9-]+)$")
TODO_TOGGLE_RE = re.compile(r"^/api/todos/([a-f0-9-]+)/toggle$")


def load():
    try:
        with open(TODOS_FILE) as handle:
            return json.load(handle)
    except (FileNotFoundError, json.JSONDecodeError):
        return []


def save(todos):
    tmp = TODOS_FILE + ".tmp"
    with open(tmp, "w") as handle:
        json.dump(todos, handle, indent=2)
    os.replace(tmp, TODOS_FILE)


def now():
    return datetime.now(timezone.utc).isoformat()


PAGE = """<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Class Todo</title>
<style>
  :root {
    color-scheme: light dark;
    --accent: #4f46e5;
    --bg: #f6f7fb;
    --card: #ffffff;
    --text: #1f2430;
    --muted: #6b7280;
    --border: #e5e7eb;
  }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    background: var(--bg);
    color: var(--text);
    display: flex;
    justify-content: center;
    padding: 32px 16px 80px;
  }
  main { width: 100%; max-width: 560px; }
  h1 { font-size: 1.6rem; margin: 0 0 4px; }
  .subtitle { color: var(--muted); margin: 0 0 24px; font-size: 0.95rem; }
  form {
    display: flex;
    gap: 8px;
    margin-bottom: 12px;
    flex-wrap: wrap;
  }
  input[type=text] {
    flex: 1 1 200px;
    padding: 10px 12px;
    border: 1px solid var(--border);
    border-radius: 8px;
    font-size: 1rem;
  }
  input#author {
    flex: 0 1 120px;
  }
  button {
    padding: 10px 16px;
    border: none;
    border-radius: 8px;
    background: var(--accent);
    color: white;
    font-size: 1rem;
    cursor: pointer;
  }
  button:hover { opacity: 0.9; }
  ul { list-style: none; margin: 0; padding: 0; }
  li {
    display: flex;
    align-items: center;
    gap: 10px;
    background: var(--card);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 12px 14px;
    margin-bottom: 8px;
  }
  li.done .text { text-decoration: line-through; color: var(--muted); }
  .text { flex: 1; word-break: break-word; }
  .author {
    font-size: 0.75rem;
    color: var(--muted);
    background: var(--bg);
    border-radius: 999px;
    padding: 2px 8px;
    white-space: nowrap;
  }
  .del {
    background: transparent;
    color: var(--muted);
    padding: 4px 8px;
    font-size: 1.1rem;
    line-height: 1;
  }
  .del:hover { color: #dc2626; }
  .empty { color: var(--muted); text-align: center; padding: 24px 0; }
  input[type=checkbox] { width: 20px; height: 20px; accent-color: var(--accent); }
</style>
</head>
<body>
<main>
  <h1>Class Todo</h1>
  <p class="subtitle">A shared list &mdash; anything you add here, everyone can see.</p>
  <form id="add-form">
    <input type="text" id="text" placeholder="Add a todo..." required maxlength="200">
    <input type="text" id="author" placeholder="Your name" maxlength="40">
    <button type="submit">Add</button>
  </form>
  <ul id="list"></ul>
  <p class="empty" id="empty" hidden>Nothing here yet. Add the first todo!</p>
</main>
<script>
const list = document.getElementById('list');
const empty = document.getElementById('empty');
const authorInput = document.getElementById('author');
authorInput.value = localStorage.getItem('todo-author') || '';

function escapeHtml(s) {
  return s.replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
}

async function refresh() {
  const res = await fetch('/api/todos');
  const data = await res.json();
  render(data.todos);
}

function render(todos) {
  list.innerHTML = '';
  empty.hidden = todos.length !== 0;
  for (const todo of todos) {
    const li = document.createElement('li');
    if (todo.done) li.classList.add('done');
    li.innerHTML = `
      <input type="checkbox" ${todo.done ? 'checked' : ''}>
      <span class="text">${escapeHtml(todo.text)}</span>
      <span class="author">${escapeHtml(todo.author || 'anonymous')}</span>
      <button class="del" title="Delete">&times;</button>
    `;
    li.querySelector('input').addEventListener('change', () => toggle(todo.id));
    li.querySelector('.del').addEventListener('click', () => remove(todo.id));
    list.appendChild(li);
  }
}

async function toggle(id) {
  await fetch(`/api/todos/${id}/toggle`, { method: 'POST' });
  refresh();
}

async function remove(id) {
  await fetch(`/api/todos/${id}`, { method: 'DELETE' });
  refresh();
}

document.getElementById('add-form').addEventListener('submit', async (e) => {
  e.preventDefault();
  const textInput = document.getElementById('text');
  const text = textInput.value.trim();
  const author = authorInput.value.trim();
  if (!text) return;
  localStorage.setItem('todo-author', author);
  await fetch('/api/todos', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ text, author }),
  });
  textInput.value = '';
  refresh();
});

refresh();
setInterval(refresh, 4000);
</script>
</body>
</html>
"""


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, fmt, *args):
        print("%s %s" % (self.command, self.path), flush=True)

    def send_json(self, status, payload):
        raw = json.dumps(payload).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(raw)))
        self.end_headers()
        self.wfile.write(raw)

    def send_html(self, status, body):
        raw = body.encode()
        self.send_response(status)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("Content-Length", str(len(raw)))
        self.end_headers()
        self.wfile.write(raw)

    def read_json(self):
        length = int(self.headers.get("Content-Length") or 0)
        if length == 0:
            return {}
        try:
            return json.loads(self.rfile.read(length))
        except json.JSONDecodeError:
            return None

    def do_GET(self):
        if self.path == "/healthz":
            return self.send_html(200, "ok")
        if self.path in ("/", "/index.html"):
            return self.send_html(200, PAGE)
        if self.path == "/api/todos":
            return self.send_json(200, {"todos": load()})
        return self.send_json(404, {"error": "not found"})

    def do_POST(self):
        if self.path == "/api/todos":
            body = self.read_json()
            if body is None:
                return self.send_json(400, {"error": "body is not JSON"})
            text = str(body.get("text", "")).strip()
            if not text:
                return self.send_json(400, {"error": "text is required"})
            author = str(body.get("author", "")).strip() or "anonymous"
            todo = {
                "id": uuid.uuid4().hex,
                "text": text[:200],
                "author": author[:40],
                "done": False,
                "created_at": now(),
            }
            todos = load()
            todos.append(todo)
            save(todos)
            return self.send_json(201, todo)

        match = TODO_TOGGLE_RE.match(self.path)
        if match:
            todo_id = match.group(1)
            todos = load()
            for todo in todos:
                if todo["id"] == todo_id:
                    todo["done"] = not todo["done"]
                    save(todos)
                    return self.send_json(200, todo)
            return self.send_json(404, {"error": "todo not found"})

        return self.send_json(404, {"error": "not found"})

    def do_DELETE(self):
        match = TODO_ID_RE.match(self.path)
        if not match:
            return self.send_json(404, {"error": "not found"})
        todo_id = match.group(1)
        todos = load()
        remaining = [t for t in todos if t["id"] != todo_id]
        if len(remaining) == len(todos):
            return self.send_json(404, {"error": "todo not found"})
        save(remaining)
        return self.send_json(200, {"ok": True})


if __name__ == "__main__":
    os.makedirs(DATA_DIR, exist_ok=True)
    ThreadingHTTPServer(("0.0.0.0", PORT), Handler).serve_forever()

