  setStatus(`Converting ${file.name}...`);
  const formData = new FormData();
  formData.append('file', file);
  try {
    const res = await fetch('/convert', { method: 'POST', body: formData });
    if (!res.ok) {
      const text = await res.text();
      setStatus(text || `Error ${res.status}`, 'error');
      return;
